SELECT CASE WHEN c.credit_limit >= 13100 THEN 'high' WHEN c.credit_limit >= 5200 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MIN(a.opened_date) AS first_opened_date FROM accounts a LEFT JOIN customers c ON a.customer_id = c.id WHERE a.opened_date < '2024-09-08' GROUP BY CASE WHEN c.credit_limit >= 13100 THEN 'high' WHEN c.credit_limit >= 5200 THEN 'mid' ELSE 'low' END ORDER BY credit_limit_bucket DESC, first_opened_date
